// الفصل الثالث: الضرب
import { AR, fmt, rnd, pick, shuf } from './mathkit.js';
import { $, $$, num, lst, mcq, ch, open, fld, fnq, calc, star } from './engine.js';
import { KB, T2, A, MX, r10, cmpS, estQ, addQ, mulQ, roundTo, sortedStr } from './kit5.js';

const mx = s => `<span class="mx"><b class="n">${AR(s)}</b></span>`;
/** ضربٌ ذهنيّ بعدِّ الأصفار */
const zQ = (tag, a, b, o = {}) => { const za = String(a).match(/0*$/)[0].length, zb = String(b).match(/0*$/)[0].length, fa = a / 10 ** za, fb = b / 10 ** zb, f = fa * fb;
  return num(tag, o.text || `أوجدْ ناتجَ الضربِ ذهنيًّا: ${mx(`${a} × ${b}`)}`, a * b, { skill: 'zeros', sol: [`الحقيقةُ الأساسيّة: ${AR(fa)} × ${AR(fb)} = ${AR(f)}`, `عددُ الأصفار: ${AR(za)} + ${AR(zb)} = ${AR(za + zb)}؛ نكتبُها عن يمينِ ${AR(f)}: ${AR(a * b)}`], hints: ['اضربِ الأرقامَ غيرَ الصفريّة (الحقيقةُ الأساسيّة).', 'ثم أضفْ عن يمينِ الناتجِ عددَ الأصفارِ في العاملين.'], ...o }); };
/** خاصّيّةُ التوزيع */
const distQ = (tag, a, t, u, o = {}) => fld(tag, o.text || `أعدْ كتابةَ ${mx(`${a} × (${t} + ${u})`)} باستعمالِ خاصّيّةِ التوزيع، ثم أوجدِ الناتج.`, [[`${AR(a)} × ${AR(t)}`, a * t], [`${AR(a)} × ${AR(u)}`, a * u], ['الناتج', a * (t + u)]], { skill: 'dist', sol: [`${AR(a)} × (${AR(t)} + ${AR(u)}) = (${AR(a)} × ${AR(t)}) + (${AR(a)} × ${AR(u)})`, `= ${AR(a * t)} + ${AR(a * u)} = ${AR(a * (t + u))}`], ...o });
const dmQ = (tag, a, n, o = {}) => { const t = Math.floor(n / 10) * 10, u = n % 10; return num(tag, o.text || `استعملْ خاصّيّةَ التوزيعِ لإيجادِ ناتجِ الضربِ ذهنيًّا: ${mx(`${a} × ${n}`)}`, a * n, { skill: 'dist', sol: [`${AR(n)} = ${AR(t)} + ${AR(u)}`, `${AR(a)} × ${AR(n)} = (${AR(a)} × ${AR(t)}) + (${AR(a)} × ${AR(u)}) = ${AR(a * t)} + ${AR(a * u)} = ${AR(a * n)}`], ...o }); };
const PROPS = ['خاصّيّةُ الإبدال', 'خاصّيّةُ التجميع', 'خاصّيّةُ العنصرِ المحايدِ الضربيّ'];
const mpropQ = (tag, expr, k, o = {}) => ch(tag, o.text || `حدّدْ خاصّيّةَ الضربِ المستعملةَ في: ${mx(expr)}`, PROPS, k, { skill: 'mprop', sol: [['تغيّرَ ترتيبُ العوامل فقط.', 'تغيّرَ العاملانِ اللذانِ نبدأُ بهما الضرب (موضعُ الأقواس).', 'ضربْنا في ١ فبقيَ العددُ نفسُه.'][k]], ...o });
const mmQ = (tag, expr, v, how, o = {}) => num(tag, o.text || `استعملْ خصائصَ الضربِ لإيجادِ الناتجِ ذهنيًّا: ${mx(expr)}`, v, { skill: 'mmental', sol: how, ...o });
const eQ = (tag, a, b, est, o = {}) => estQ(tag, `${a} * ${b}`, est, { text: o.text || `قدّرْ ناتجَ الضرب: ${mx(`${a} × ${b}`)}`, how: o.how || estHow(a, b), ...o });
function estHow(a, b) { const ra = roundTo(a, Math.max(0, String(a).length - 1)), rb = roundTo(b, Math.max(0, String(b).length - 1)); return `نقرّبُ: ${AR(a)} ← ${AR(ra)} و${AR(b)} ← ${AR(rb)}، ثم ${AR(ra)} × ${AR(rb)} = ${AR(ra * rb)}`; }
const estAny = (a, b) => roundTo(a, Math.max(0, String(a).length - 1)) * roundTo(b, Math.max(0, String(b).length - 1));
/** مصفوفةُ قطعِ العدّ: ضربٌ ذهنيٌّ بالنواتجِ الجزئيّة */
function arraySVG(r, c) { const t = Math.floor(c / 10) * 10, u = c - t; let g = ''; for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) { const x = (c - 1 - j) * 14 + (j >= u ? 0 : 0) + (j < u ? 0 : 8), y = i * 14; g += `<circle cx="${x + 7 + (j < u ? -8 : 0) + 8}" cy="${y + 7}" r="5.5" fill="${j < u ? '#e8503a' : '#f2c230'}" stroke="#8a6a10" stroke-width=".6"/>`; } return `<svg viewBox="0 0 ${c * 14 + 18} ${r * 14 + 2}" style="max-width:${Math.min(460, c * 16)}px;width:100%;direction:ltr">${g}</svg>`; }
function arrTool(el) {
  el.innerHTML = `<div class="row">الصفوف <input type="range" min="2" max="9" value="4" class="ar"> الأعمدة <input type="range" min="11" max="29" value="13" class="ac"></div><div class="aout"></div>`;
  const draw = () => { const r = +$('.ar', el).value, c = +$('.ac', el).value, t = Math.floor(c / 10) * 10, u = c - t; $('.aout', el).innerHTML = arraySVG(r, c) + `<div class="keybox">${AR(r)} × ${AR(c)} = (${AR(r)} × ${AR(t)}) + (${AR(r)} × ${AR(u)}) = ${AR(r * t)} + ${AR(r * u)} = <b>${AR(r * c)}</b></div>`; };
  $$('input', el).forEach(i => i.oninput = draw); draw();
}

/* ═════════ المولّدات ═════════ */
const G = {
  zeros: L => { const a = rnd(1, 9) * 10 ** rnd(0, L ? 3 : 2), b = rnd(1, 9) * 10 ** rnd(1, L ? 3 : 2); return zQ('', Math.random() < .5 ? a : b, Math.random() < .5 ? b : a); },
  dist: L => { const a = rnd(2, 9), n = rnd(11, L ? 99 : 59); return Math.random() < .5 ? dmQ('', a, n) : distQ('', a, Math.floor(n / 10) * 10, n % 10 || 1); },
  mest: L => { const a = rnd(11, L ? 999 : 99), b = rnd(L ? 11 : 3, L ? 99 : 9); return eQ('', a, b, estAny(a, b)); },
  mul1: L => mulQ('', rnd(L ? 100 : 11, L ? 999 : 99), rnd(2, 9)),
  mul2: L => mulQ('', rnd(L ? 100 : 11, L ? 999 : 99), rnd(11, 99)),
  mprop: L => { const a = rnd(2, 30), b = rnd(2, 30), c = rnd(2, 30), k = rnd(0, 2); return mpropQ('', k === 0 ? `${a} × ${b} = ${b} × ${a}` : k === 1 ? `(${a} × ${b}) × ${c} = ${a} × (${b} × ${c})` : `${a} × 1 = ${a}`, k); },
  mmental: L => { const [p, q] = pick([[2, 5], [4, 25], [5, 20], [2, 50], [4, 5], [25, 8]]); const x = rnd(3, 60); return mmQ('', `${p} × ${x} × ${q}`, p * x * q, [`نبدّلُ الترتيبَ ونجمّعُ ${AR(p)} و${AR(q)}: (${AR(p)} × ${AR(q)}) × ${AR(x)}`, `${AR(p * q)} × ${AR(x)} = ${AR(p * q * x)}`]); },
  draw: L => { const L0 = rnd(10, 30) * 10, w = pick([20, 30, 40]), g = pick([10, 15, 20]), e = g; const n = Math.floor((L0 - 2 * e + g) / (w + g)); return num('', `ارسمْ صورة: قطعةُ أرضٍ طولُها ${AR(L0)} م على الشارع، يريدُ مهندسٌ أن يبنيَ عليها فللًا عرضُ كلٍّ منها ${AR(w)} م، ويتركَ ${AR(g)} م بينَ كلِّ فيلّا وأخرى، و${AR(e)} م عندَ كلٍّ من الطرفين. كم فيلّا يمكنُه بناؤها؟`, n, { skill: 'draw', sol: [`الطولُ المتاحُ بعدَ الطرفين: ${AR(L0)} − ${AR(2 * e)} = ${AR(L0 - 2 * e)}`, `كلُّ فيلّا تحتاجُ ${AR(w)} م، وبينَ كلِّ فيلّتين ${AR(g)} م: ${AR(n)} × ${AR(w)} + ${AR(n - 1)} × ${AR(g)} = ${AR(n * w + (n - 1) * g)} ≤ ${AR(L0 - 2 * e)}`] }); },
};
const GN = { zeros: 'الضرب الذهني بعد الأصفار', dist: 'خاصية التوزيع', mest: 'تقدير نواتج الضرب', mul1: 'الضرب في عدد من رقم واحد', mul2: 'الضرب في عدد من رقمين', mprop: 'خصائص الضرب', mmental: 'الضرب الذهني بالخصائص', draw: 'رسم صورة' };

